import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const alseilStatusScenarios=['confusion-ordinary','confusion-dedicated','mirror-seal-ordinary','mirror-seal-dedicated','hypnosis-ordinary','hypnosis-dedicated','confusion-recovery-ordinary','confusion-recovery-dedicated','mirror-seal-recovery-ordinary','mirror-seal-recovery-dedicated','hypnosis-recovery-ordinary','hypnosis-recovery-dedicated'] as const;
export type AlseilStatusScenario=typeof alseilStatusScenarios[number];
export function isAlseilStatusScenario(name:string):name is AlseilStatusScenario{return (alseilStatusScenarios as readonly string[]).includes(name);}
export function alseilStatusMode(name:AlseilStatusScenario){const confusion=name.startsWith('confusion'),mirror=name.startsWith('mirror'),dedicated=name.endsWith('dedicated');return {card:confusion?'a2-p13-r1c2':mirror?'a2-p13-r1c3':'a2-p13-r2c1',name:confusion?'錯乱':mirror?'鏡封':'催眠',confusion,mirror,dedicated,use:4,effect:dedicated?(mirror?7:5):4,damage:null,modifier:-2,recovery:mirror||confusion&&dedicated?-2:-1,modifiers:mirror||confusion&&dedicated?[-2]:[-2,-1],kind:confusion?'ability-disabled' as const:'stopped' as const,attributes:mirror?['魔']:['魔','精']};}
export function makeAlseilStatusScenario(name:AlseilStatusScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;followers?:boolean;aura?:boolean}={}){
 const m=alseilStatusMode(name);let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,options.owner??'占星術師のアルセイル');assignCharacter(s,b,options.aura?'リーア姫':'侍大将のシン');assignCharacter(s,c,options.aura?'聖騎士ランスロット':'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};s.players[a]!.permanent!.magic_level=20+(options.level??4)-gameStats(s,a).magic_level;s.players[a]!.permanent!.spirit=20+6-gameStats(s,a).spirit;s.players[b]!.permanent!.spirit=20+6-gameStats(s,b).spirit;
 const card=takeCard(s,a,m.card),maai=takeCard(s,b,'a2-p07-r1c1'),evade=takeCard(s,b,'a2-p05-r3c1'),fate=takeCard(s,c,'命運凶変'),teleport=options.followers?null:takeCard(s,b,'a2-p06-r1c1'),book=options.followers?null:takeCard(s,b,'魔導書'),guards=options.followers?[takeCard(s,b,'水竜'),takeCard(s,b,'砦')]:[],other=options.followers?takeCard(s,c,'兵士'):null;for(const id of [a,b,c,d])trimHand(s,id,card,maai,evade,fate,...guards,...(teleport?[teleport]:[]),...(book?[book]:[]),...(other?[other]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(name.includes('-recovery-')?6:1)},r=transition(s,input,e);if(!r.ok)throw Error(`ALSEIL_STATUS_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('ALSEIL_STATUS_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('ALSEIL_STATUS_IDS');}
 for(const id of [a,b,c,d]){if(id===b)for(const guard of guards)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:guard});if(other&&id===c)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:other});act(id,{type:'PASS_SETUP'});}act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(name.includes('-recovery-')){act(a,{type:'ATTACK',cardInstanceId:card,targetIds:m.dedicated?[b,c]:[b],dedicated:m.dedicated});for(let n=0;n<300&&s.windows?.length;n++){const w=s.windows.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'});}if(!s.players[b]!.statuses?.some(t=>t.kind===m.kind))throw Error('ALSEIL_STATUS_FIXTURE_STATUS');}return s;
}
